    document.getElementById(this.mapId).innerHTML = `<div
        id="map"
        style="
          background-color: #99d9f2;
          width: 100vw;
          height: 100vh;
          position: fixed;
        "
      ></div>`;
    function centerMap(e) {
      this.map.panTo(e.latlng);
    }
    function zoomIn() {
      this.map.zoomIn();
    }

    function zoomOut() {
      this.map.zoomOut();
    }
    function reset() {
      this.map.fitBounds(WORLD_MAP_BOUNDS, { animate: false });
    }
    function gameRules() {
      this.gameRulesFunction();
    }
